/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        propName: 'popoverParams',
        value: {
            "sysId": api.item.value.sys_id,
            "table": api.item.value.table
        }
    };
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		route: "sow-device",
		fields: {
			sysid: event.context.item.value.computer_sysid
		},
		params: {
			tab: "device-health-overview"
		},
		redirect: null,
		passiveNavigation: null,
		title: null,
		multiInstField: null,
		targetRoute: "current",
		external: null,
		navigationOptions: null
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	var table = api.context.props.parentTable;
	if(table) {
		var tableCaps = table.charAt(0).toUpperCase() + table.slice(1);
		return {
			event: "View Device Health From " + tableCaps,
			value: {
				"source": "Record information"
			}
		};
	}
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        propName: 'popoverParams',
        value: {
            "sysId": api.item.value.sys_id,
            "table": api.item.value.table
        }
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        route: "record",
        fields: {
            table: api.state.popoverParams.table,
            sysId: api.state.popoverParams.sysId
        },
        params: null,
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: null,
        targetRoute: "current",
        external: null,
        navigationOptions: null
    };
}
